};

/** session_detail 调用清单（抽屉转录重查的观察锚）。 */
function sessionDetailCalls(): unknown[][] {
  return invokeMock.mock.calls.filter(([name]) => name === 'session_detail');
}

function checklistEnvelope(): ArtifactEnvelope {
