  it('边界：sessionId 缺席（旧条目）→ 无反查兜底，呈「此步无会话记录」空态（react 面零取数）', async () => {
    // sourceRef 定式反查退役：槽位 sessionId 缺席即无会话可寻址，不得按定式回退
